PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS supermarkets(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,address TEXT NOT NULL DEFAULT '',map_width INTEGER NOT NULL DEFAULT 1200,map_height INTEGER NOT NULL DEFAULT 760,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS aisles(id INTEGER PRIMARY KEY AUTOINCREMENT,supermarket_id INTEGER NOT NULL REFERENCES supermarkets(id) ON DELETE CASCADE,code TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'aisle',x INTEGER NOT NULL,y INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,UNIQUE(supermarket_id,code));
CREATE TABLE IF NOT EXISTS entrances(id INTEGER PRIMARY KEY AUTOINCREMENT,supermarket_id INTEGER NOT NULL REFERENCES supermarkets(id) ON DELETE CASCADE,name TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,supermarket_id INTEGER NOT NULL REFERENCES supermarkets(id) ON DELETE CASCADE,aisle_id INTEGER REFERENCES aisles(id) ON DELETE SET NULL,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'General',sku TEXT NOT NULL DEFAULT '',price REAL NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,bay INTEGER NOT NULL DEFAULT 1,shelf TEXT NOT NULL DEFAULT 'Eye level',available INTEGER NOT NULL DEFAULT 1,x INTEGER NOT NULL,y INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS product_search ON products(supermarket_id,name);
